package com.learningplatform.modules.tutoring.mapper;
/** Fixed SQL statement catalogue; services only pass typed statement identifiers and bound values. */
public enum TutoringSql {
 FIND_POLICY_VERSION("SELECT version FROM ai_policies WHERE id=?"),
 FIND_CURRENT_POLICY_VERSION("SELECT p.version FROM assignments a JOIN ai_policies p ON p.id=a.current_ai_policy_id WHERE a.id=?"),
 FIND_OWNED_DELIVERED_REQUEST("SELECT * FROM tutoring_requests WHERE id=? AND student_id=? AND assignment_id=? AND status IN ('completed','fallback')"),
 FIND_POLICY("SELECT * FROM ai_policies WHERE id=?"),
 INSERT_POLICY("INSERT INTO ai_policies(id,assignment_id,version,config,created_by,created_at) VALUES(?,?,?,?,?,?)"),
 LIST_SESSIONS("SELECT s.*, (SELECT r.id FROM tutoring_requests r WHERE r.session_id=s.id AND r.status IN ('queued','running') LIMIT 1) pending_request_id,(SELECT MAX(m.created_at) FROM tutoring_messages m WHERE m.session_id=s.id) last_message_at FROM tutoring_sessions s WHERE s.assignment_id=? AND s.student_id=? ORDER BY COALESCE((SELECT MAX(m.created_at) FROM tutoring_messages m WHERE m.session_id=s.id),s.created_at) DESC,s.id DESC LIMIT ? OFFSET ?"),
 COUNT_SESSIONS("SELECT COUNT(*) FROM tutoring_sessions WHERE assignment_id=? AND student_id=?"),
 INSERT_SESSION("INSERT INTO tutoring_sessions(id,assignment_id,student_id,created_at,updated_at) VALUES(?,?,?,?,?)"),
 LIST_MESSAGES("SELECT m.*,p.version,r.content_expires_at,r.result FROM tutoring_messages m JOIN tutoring_requests r ON r.id=m.tutoring_request_id LEFT JOIN ai_policies p ON p.id=m.policy_id WHERE m.session_id=? ORDER BY m.sequence LIMIT ? OFFSET ?"),
 COUNT_MESSAGES("SELECT COUNT(*) FROM tutoring_messages WHERE session_id=?"),
 FIND_PENDING_REQUEST("SELECT id FROM tutoring_requests WHERE student_id=? AND assignment_id=? AND status IN ('queued','running')"),
 FIND_PROGRESS("SELECT highest_delivered_hint_level FROM tutoring_progress WHERE student_id=? AND assignment_id=?"),
 COUNT_USER_BUDGET("SELECT COUNT(*) FROM tutoring_requests WHERE student_id=? AND created_at>=? AND (status IN ('queued','running','completed','fallback') OR provider_call_count>0) AND COALESCE(error_code,'') NOT IN ('PROVIDER_UNAVAILABLE','PROVIDER_RESULT_UNKNOWN','INTERNAL_ERROR')"),
 COUNT_ASSIGNMENT_BUDGET("SELECT COUNT(*) FROM tutoring_requests WHERE student_id=? AND assignment_id=? AND created_at>=? AND (status IN ('queued','running','completed','fallback') OR provider_call_count>0) AND COALESCE(error_code,'') NOT IN ('PROVIDER_UNAVAILABLE','PROVIDER_RESULT_UNKNOWN','INTERNAL_ERROR')"),
 COUNT_MINUTE_BUDGET("SELECT COUNT(*) FROM tutoring_requests WHERE student_id=? AND created_at>=? AND (status IN ('queued','running','completed','fallback') OR provider_call_count>0) AND COALESCE(error_code,'') NOT IN ('PROVIDER_UNAVAILABLE','PROVIDER_RESULT_UNKNOWN','INTERNAL_ERROR')"),
 INSERT_REQUEST("INSERT INTO tutoring_requests(id,session_id,student_id,assignment_id,action,content,student_attempt,workspace_revision,workspace_snapshot,hint_level,content_expires_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)"),
 FIND_PENDING_AFTER_CONFLICT("SELECT id FROM tutoring_requests WHERE student_id=? AND assignment_id=? AND status IN ('queued','running')"),
 FIND_OWNED_REQUEST("SELECT * FROM tutoring_requests WHERE id=? AND student_id=?"),
 FIND_OWNED_SESSION("SELECT * FROM tutoring_sessions WHERE id=? AND student_id=?"),
 FIND_NEXT_SEQUENCE("SELECT next_message_sequence FROM tutoring_sessions WHERE id=?"),
 ADVANCE_SEQUENCE("UPDATE tutoring_sessions SET next_message_sequence=next_message_sequence+1,updated_at=? WHERE id=? AND next_message_sequence=?"),
 INSERT_MESSAGE("INSERT INTO tutoring_messages(id,session_id,tutoring_request_id,sequence,role,content,mode,hint_level,policy_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)"),
 RECOVER_RUNNING("UPDATE tutoring_requests SET status='failed',error_code='PROVIDER_RESULT_UNKNOWN',completed_at=?,updated_at=? WHERE status='running'"),
 LIST_QUEUED("SELECT id FROM tutoring_requests WHERE status='queued' ORDER BY created_at,id LIMIT 16"),
 PURGE_MESSAGES("UPDATE tutoring_messages m JOIN tutoring_requests r ON r.id=m.tutoring_request_id SET m.content=NULL,m.content_purged_at=? WHERE r.content_expires_at<=? AND m.content_purged_at IS NULL"),
 PURGE_DISCLOSURE("UPDATE tutoring_progress p SET disclosure_summary=NULL,content_purged_at=? WHERE EXISTS (SELECT 1 FROM tutoring_requests r WHERE r.student_id=p.student_id AND r.assignment_id=p.assignment_id AND r.content_expires_at<=?)"),
 PURGE_REQUESTS("UPDATE tutoring_requests SET content=NULL,student_attempt=NULL,workspace_snapshot=NULL,result=CASE WHEN result IS NULL THEN NULL ELSE JSON_SET(result,'$.content',NULL,'$.contentUnavailableReason','retention_expired') END,content_purged_at=? WHERE content_expires_at<=? AND content_purged_at IS NULL AND status NOT IN ('queued','running')"),
 CLAIM_REQUEST("UPDATE tutoring_requests SET status='running',started_at=?,updated_at=? WHERE id=? AND status='queued'"),
 FIND_REQUEST("SELECT * FROM tutoring_requests WHERE id=?"),
 LIST_REVIEWED_HISTORY("SELECT content,student_attempt,result,content_expires_at,content_purged_at FROM tutoring_requests WHERE student_id=? AND assignment_id=? AND status='completed' ORDER BY created_at DESC LIMIT 8"),
 COUNT_EXPIRED_HISTORY("SELECT COUNT(*) FROM tutoring_requests WHERE student_id=? AND assignment_id=? AND status='completed' AND (content_expires_at<=? OR content_purged_at IS NOT NULL)"),
 COUNT_DISCLOSED_CHARACTERS("SELECT COALESCE(SUM(CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(result,'$.content')))),0) FROM tutoring_requests WHERE student_id=? AND assignment_id=? AND status='completed'"),
 STATIC_CHECK_SNAPSHOT("SELECT policy_snapshot,result,workspace_revision FROM assignment_checks WHERE assignment_id=? AND student_id=? AND status='completed' AND result IS NOT NULL ORDER BY workspace_revision DESC LIMIT 1"),
 ASSIGNMENT_RESOURCES("SELECT r.id,r.title,r.content_markdown,r.position FROM resources r WHERE r.offering_id=? AND r.status='active' AND (r.knowledge_point_id IN (SELECT knowledge_point_id FROM assignment_knowledge_points WHERE assignment_id=?) OR r.chapter_id=(SELECT chapter_id FROM assignments WHERE id=?)) ORDER BY r.position,r.id LIMIT 20"),
 OFFERING_RESOURCES("SELECT r.id,r.title,r.content_markdown,r.position FROM resources r WHERE r.offering_id=? AND r.status='active' ORDER BY r.position,r.id LIMIT 20"),
 RESERVE_PROVIDER_CALL("UPDATE tutoring_requests SET provider_call_count=provider_call_count+1,generation_policy_id=?,updated_at=? WHERE id=? AND status='running' AND provider_call_count<2"),
 ACCUMULATE_USAGE("UPDATE tutoring_requests SET input_tokens=CASE WHEN provider_call_count=1 THEN ? WHEN input_tokens IS NULL OR ? IS NULL THEN NULL ELSE input_tokens+? END,output_tokens=CASE WHEN provider_call_count=1 THEN ? WHEN output_tokens IS NULL OR ? IS NULL THEN NULL ELSE output_tokens+? END WHERE id=? AND status='running'"),
 FIND_DELIVERY_MEMBERSHIP("SELECT m.status member_status,o.status offering_status FROM course_offerings o LEFT JOIN offering_members m ON m.offering_id=o.id AND m.user_id=? AND m.role='student' WHERE o.id=?"),
 FIND_DELIVERY_REQUEST("SELECT * FROM tutoring_requests WHERE id=?"),
 FIND_GENERATION_POLICY_VERSION("SELECT version FROM ai_policies WHERE id=?"),
 DELIVER_REQUEST("UPDATE tutoring_requests r JOIN assignments a ON a.id=r.assignment_id JOIN course_offerings o ON o.id=a.offering_id JOIN offering_members m ON m.offering_id=o.id AND m.user_id=r.student_id AND m.role='student' SET r.status=?,r.result=?,r.error_code=?,r.fallback_reason=?,r.review_policy_id=?,r.review_version='rules-v1',r.reviewed_at=?,r.completed_at=?,r.updated_at=? WHERE r.id=? AND r.status='running' AND a.current_ai_policy_id=? AND a.status='published' AND o.status='active' AND m.status='active'"),
 ADVANCE_PROGRESS("INSERT INTO tutoring_progress(id,assignment_id,student_id,highest_delivered_hint_level,disclosure_version,created_at,updated_at) VALUES(?,?,?,?,1,?,?) ON DUPLICATE KEY UPDATE highest_delivered_hint_level=GREATEST(highest_delivered_hint_level,?),disclosure_version=disclosure_version+1,updated_at=?"),
 FAIL_REQUEST("UPDATE tutoring_requests SET status='failed',result=NULL,error_code=?,completed_at=?,updated_at=? WHERE id=? AND status='running'");
 final String text;TutoringSql(String text){this.text=text;}
}
